template.query:
mutation ManageUserAccess($action: UserAction!, $input: UserManagementInput!) {
  userManagement(action: $action, input: $input) {
    success
    user {
      id
      username
      email
      roles {
        name
        permissions {
          resource
          actions
        }
      }
      status
      lastLogin
      createdAt
    }
    permissions {
      granted
      revoked
      current {
        tables {
          name
          access
        }
        operations {
          name
          allowed
        }
        features {
          name
          enabled
        }
      }
    }
    auditLog {
      action
      timestamp
      performedBy
      target
      changes
    }
    errors {
      message
      field
      code
    }
  }
}
